import React from 'react';

class QueueItem extends React.Component {
    render() {
        const {queue, selected, onSelect} = this.props;

        return (
            <tr onClick={onSelect} className={ selected === queue.name ? "selected" : "none" }>
                <td>{queue.name}</td>
                <td>{queue.count}</td>
                <td>{queue.outOfRetries}</td>
                <td>{queue.nextQueue}</td>
            </tr>
        )
    }
}

export default QueueItem;
