import React from 'react';
import moment from 'moment';

class MessageItem extends React.Component {
    constructor(props) {
        super(props);
        this.state = { message: props.message };
    }

    toggleMessage = () => {
        const message = this.state.message;
        message.selected = !message.selected;
        this.setState({ message: message }, () => this.props.onComponentRefresh(message));
    }

    render() {
        const {allMessages, onEdit} = this.props;
        const message = this.state.message;

        return (
            <tr className={ message.selected || allMessages ? "selected" : "none" }>
                <td className="selectRow">
                    <input type="checkbox" name={message.messageCorrelation} checked={message.selected || allMessages} disabled={ allMessages }
                        onChange={this.toggleMessage} />
                </td>
                <td>{message.messageCorrelation}</td>
                <td>{moment(message.entryDate).format("DD.MM.YYYY HH:mm:ss")}</td>
                <td>{moment(message.dueDate).format("DD.MM.YYYY HH:mm:ss")}</td>
                <td>{message.retries}</td>
                <td><div className="contentCell">{message.header}</div></td>
                <td><div className="contentCell">{message.payload}</div></td>
                <td><input onClick={(evt) => onEdit(evt, message)} type="button" value="&#x2630;"/></td>
            </tr>
        )
    }
}

export default MessageItem;
