import React from 'react';
import MessageItem from './MessageItem';
import moment from 'moment';
import axios from 'axios';

const queuesUri = window.contextRoot + '/queues';

class MessageTable extends React.Component {
    constructor(props) {
        super(props);
        this.state = { allMessages: false, newQueue: undefined, messages: [], newDate: moment().format("YYYY-MM-DDTHH:mm:ss"), errorMessage: '',
            toUpdate: { messageCorrelation: '', header: '', payload: '', priority: 0 }
        };
    }

    toggleAllMessages = () => {
        this.setState({ allMessages: !this.state.allMessages });
    }

    selectNewQueue = (event) => {
        this.setState({ newQueue: event.target.value });
    }

    updateNewDate = (event) => {
        this.setState({ newDate: event.target.value });
    }

    messageSelected = () => {
        if (this.state.allMessages) {
            return true;
        };
        return this.props.messages.find((message) => message.selected) != null;
    }

    static getDerivedStateFromProps(props, state) {
        if (props.messages) {
            return { messages: props.messages };
        }
        return null;
    }

    onComponentRefresh = (updatedMessage) => {
        let messages = this.state.messages;
        console.log("Refresh message " + updatedMessage.messageCorrelation);
        let message = messages.find((m) => (m.messageCorrelation === updatedMessage.messageCorrelation));
        if (message) {
            message.selected = updatedMessage.selected;
            this.setState({ messages: messages });
        }
    }

    closeDialog = () => {
        this.setState({ errorMessage: null }, () => {
            const dialog = document.getElementById('validationMessage');
            dialog.close();
        });
    }

    move = () => {
        if (!this.state.newQueue) {
            this.setState({ errorMessage: "New queue is empty"}, () => {
                const dialog = document.getElementById("validationMessage");
                dialog.showModal();
            });
            return;
        }
        let messages = this.selectedMessages();
        const request = {
            action: "MOVE",
            messages: messages,
            targetQueue: this.state.newQueue
        }
        console.log("Move " + messages.length + " messages from " + this.props.selected + " to " + this.state.newQueue);
        this.sendOperationsRequest(this.props.selected, request);
    }

    retry = () => {
        let messages = this.selectedMessages();
        const request = {
            action: "RETRY",
            messages: messages
        }
        console.log("Retry " + messages.length + " messages in " + this.props.selected);
        this.sendOperationsRequest(this.props.selected, request);
    }

    reschedule = () => {
        if (!this.state.newDate) {
            this.setState({ errorMessage: "New Due Date is empty"}, () => {
                const dialog = document.getElementById("validationMessage");
                dialog.showModal();
            });
            return;
        }
        let messages = this.selectedMessages();
        const deliveryOffset = moment.duration(moment(this.state.newDate, "YYYY-MM-DDTHH:mm:ss")
            .diff(moment())).asMilliseconds();
        const request = {
            action: "RESCHEDULE",
            messages: messages,
            deliveryOffset: deliveryOffset
        }
        console.log("Reschedule " + messages.length + " to " + this.state.newDate + " in " + this.props.selected);
        this.sendOperationsRequest(this.props.selected, request);
    }

    remove = () => {
        let messages = this.selectedMessages();
        const request = {
            action: "DEQUEUE",
            messages: messages
        }
        console.log("Remove " + messages.length + " messages in " + this.props.selected);
        this.sendOperationsRequest(this.props.selected, request);
    }

    sendOperationsRequest = async (queue, request) => {
        const uri = `${queuesUri}/${queue}`;
        try {
            await axios.post(uri, request);
            // deselect all messages
            this.state.messages.map((message) => message.selected = false);
            this.setState({ messages: this.state.messages, allMessages: false }, () => this.props.onComponentRefresh(queue));
        } catch (error) {
            this.setState({ errorMessage: error.message }, () => {
                const dialog = document.getElementById("validationMessage");
                dialog.showModal();
            });
        }
    }

    selectedMessages() {
        if (this.state.allMessages) {
            return this.state.messages;
        }

        return this.state.messages.filter((message) => message.selected);
    }

    selectPage(evt, page) {
        evt.preventDefault();
        if (this.props.currentPage !== page) {
            this.props.onComponentRefresh(this.props.selected, this.props.messages, this.props.queues, this.props.pageCount, this.props.pageSize, page);
        }
    }

    editMessage(evt, message) {
        evt.preventDefault();
        this.setState({ toUpdate: message}, () => {
            const dialog = document.getElementById("editMessage");
            dialog.showModal();
        });
    }

    closeEditor = () => {
        this.setState({ toUpdate: { messageCorrelation: '', header: '', payload: '', priority: 0 }, errorMessage: '' }, () => {
            const dialog = document.getElementById('editMessage');
            dialog.close();
        });
    }

    updateMessage = async () => {
        try {
            let message = this.state.toUpdate;
            console.log(message);
            const uri = `${queuesUri}/${message.queue}/${message.messageCorrelation}`;
            await axios.put(uri, message);
            this.setState({ toUpdate: { messageCorrelation: '', header: '', payload: '', priority: 0 }, errorMessage: '' }, () => {
                const dialog = document.getElementById('editMessage');
                dialog.close();
            });
        } catch (error) {
            this.setState({ errorMessage: error.message});
        }
    }

    updateCorrelation = (event) => {
        const toUpdate = this.state.toUpdate;
        toUpdate.messageCorrelation = event.target.value;
        this.setState( { toUpdate: toUpdate })
    }

    updateHeader = (event) => {
        const toUpdate = this.state.toUpdate;
        toUpdate.header = event.target.value;
        this.setState( { toUpdate: this.state.toUpdate })
    }

    updatePayload = (event) => {
        const toUpdate = this.state.toUpdate;
        toUpdate.payload = event.target.value;
        this.setState( { toUpdate: toUpdate })
    }

    updatePriority = (event) => {
        const toUpdate = this.state.toUpdate;
        toUpdate.priority = event.target.value;
        this.setState( { toUpdate: toUpdate })
    }

    render() {
        const {queues, pageSize, currentPage, pageCount} = this.props;
        return (
            <table>
                <caption>
                    <span className="buttons">
                        <label>New Queue
                            <select name="newQueue" id="newQueue" value={ this.state.newQueue } onChange={ this.selectNewQueue }>
                                <option/>
                                {queues.map((queue) => (
                                    <option key={queue.name} value={queue.name}>{queue.name}</option>
                                ))}
                            </select>
                        </label>
                        <button id="btnMove" type="button" disabled={ !this.messageSelected() } onClick={this.move}>Move messages</button>
                        <label>New Due Date
                            <input className="date" id="newDate" type="datetime-local" step="1"
                                value={this.state.newDate} onChange={evt => this.updateNewDate(evt)}/>
                        </label>
                        <button id="btnReschedule" type="button" disabled={ !this.messageSelected() } onClick={this.reschedule}>Reschedule messages</button>
                        <button id="btnRetry" type="button" disabled={ !this.messageSelected() } onClick={this.retry}>Retry messages</button>
                        <button id="btnRemove" type="button" disabled={ !this.messageSelected() } onClick={this.remove}>Remove messages</button>
                    </span>
                    <dialog id="validationMessage">
                        <h1>Invalid action</h1>
                        <p className="errorMessage">{ this.state.errorMessage }</p>
                        <button id="btnClose" onClick={this.closeDialog}>Close</button>
                    </dialog>
                    <dialog id="editMessage">
                        <h1>Edit message</h1>
                        <p className="errorMessage">{ this.state.errorMessage }</p>
                        <div className="values">
                            <p><span>Correlation:</span><input type="text" size="80" value={ this.state.toUpdate?.messageCorrelation } onChange={this.updateCorrelation} /></p>
                            <p><span>Header:</span><input type="text" size="80" value={ this.state.toUpdate?.header } onChange={this.updateHeader} /></p>
                            <p><span>Payload:</span><textarea value={ this.state.toUpdate?.payload } onChange={ this.updatePayload } /></p>
                            <p><span>Priority:</span><input type="number" min="-100" max="100" value={ this.state.toUpdate?.priority } onChange={this.updatePriority} /></p>
                        </div>
                        <button id="btnSave" onClick={this.updateMessage}>Save</button>
                        <button id="btnCancel" onClick={this.closeEditor}>Cancel</button>
                    </dialog>
                </caption>
                <thead>
                    <tr>
                        <th className="selectRow"><input id="chkAllMessages" type="checkbox" name="allmessages" checked={ this.state.allMessages } onChange={this.toggleAllMessages}/></th>
                        <th style={{ width: 225 }}>Correlation</th>
                        <th className="date">Entry date</th>
                        <th className="date">Due Date</th>
                        <th style={{ width: 40 }}>Retries</th>
                        <th style={{ width: 250 }}>Header</th>
                        <th>Payload</th>
                        <th className="selectRow"></th>
                    </tr>
                </thead>
                <tbody id="messageTable">
                    {this.state.messages.map((message) => (
                        <MessageItem key={message.messageCorrelation} message={message} allMessages={ this.state.allMessages } onComponentRefresh={this.onComponentRefresh}
                            onEdit={(evt) => this.editMessage(evt, message) }/>
                    ))}
                </tbody>
                <tfoot>
                    <tr className="buttons"><td colSpan="8">
                        { Array.from(Array(Math.min(pageCount, 12)).keys()).map((page) => (
                                <a id={ "p" + (page + 1) } key={ page }
                                   className={ (page + 1 === currentPage) ? "current" : "none" }
                                   href={ "#p" + (page + 1) }
                                   onClick={ evt => this.selectPage(evt, page + 1) } >
                                    &lt;{ page * pageSize + 1} ... { (page + 1) * pageSize }&gt;</a>
                        ))}
                    </td></tr>
                </tfoot>
            </table>
        )
    }
}

export default MessageTable;
