import React from 'react';
import QueueItem from './QueueItem';
import axios from 'axios';
import moment from 'moment';

const queuesUri = window.contextRoot + '/queues';

class QueueTable extends React.Component {
    constructor(props) {
        super(props);
        this.state = { autoRefresh: false, outOfRetries: false, search: '', queues: [], pageSize: 20, loadQueues: props.requestRefresh };
    }

    componentDidMount() {
        if (this.state.loadQueues) {
            this.setState({ loadQueues: false }, () => this.loadQueues());
        }
    }

    componentWillUnmount() {
        if (this.timeout) {
            clearTimeout(this.timeout);
            this.timeout = null;
        }
    }

    componentDidUpdate(prevProps, prevState) {
        if (this.state.loadQueues && !prevState.loadQueues) {
            this.loadQueues();
        } else if (this.props.requestRefresh && !prevProps.requestRefresh) {
            this.setState({ loadQueues: true });
        } else {
            const queue = this.props.selected;
            const currentPage = this.props.currentPage;
            if (queue === prevProps.selected && currentPage !== prevProps.currentPage) {
                console.log("previous page=" + prevProps.currentPage);
                this.loadMessagesAndRefresh(queue, currentPage);
            }
        }
    }

    toggleAutoRefresh = () => {
        this.setState({ autoRefresh: !this.state.autoRefresh }, this.setTimer);
    }

    toggleOutOfRetries = () => {
        this.setState({ outOfRetries: !this.state.outOfRetries, loadQueues: true });
    }

    selectPageSize = (evt) => {
        this.setState({ pageSize: evt.target.value, loadQueues: true });
    }

    setTimer = () => {
        if (this.timeout) {
            clearTimeout(this.timeout);
            this.timeout = null;
        }
        if (this.state.autoRefresh) {
            this.loadQueues();
            this.timeout = setTimeout(this.setTimer, 5000);
        }
    }

    updateSearch = (evt) => {
        this.setState({ search: evt.target.value });
    }

    search = () => {
        this.setState({ loadQueues: true });
    }

    selectQueue(queue, doLoad) {
        if (this.props.selected !== queue || doLoad) {
            this.setState({ search: doLoad ? this.state.search : '' }, () => this.loadMessagesAndRefresh(queue, 1));
        }
    }

    loadMessagesAndRefresh(queue, currentPage) {
        const pageSize = this.state.pageSize;
        const queueItem = this.state.queues.find(q => q.name === queue);
        if (queueItem) {
            const messageCount = this.state.outOfRetries ? queueItem.outOfRetries : queueItem.count;
            const pageCount = Math.max(1, Math.ceil(messageCount / pageSize));
            this.loadMessages(queue, currentPage, pageSize, (messages) => {
                this.props.onComponentRefresh(queue, messages, this.state.queues, pageCount, pageSize, currentPage)});
        }
    }

    loadMessages = async (queue, currentPage, pageSize, onLoad) => {
        let messages = [];
        const outOfRetries = this.state.outOfRetries;
        const search = this.state.search;
        const from = (currentPage - 1) * pageSize;
        let uri;
        if (search === null || search.trim() === "") {
            uri = `${queuesUri}/${queue}?from=${from}&size=${pageSize}&outOfRetries=${outOfRetries}`
        } else {
            uri = `${queuesUri}/${queue}?from=${from}&size=${pageSize}&outOfRetries=${outOfRetries}&search=${search.trim()}`
        }
        console.log("Loading messages in " + queue + " ("+ uri + ")");
        if (queue) {
            try {
                const response = await axios.get(uri);
                messages = response.data;
            } catch (error) {
                console.log(error.message);
                if (window.generateData) {
                    const size = Math.floor(Math.random() * pageSize);
                    for (let i=0; i<size; i++) {
                        messages[i] = {
                            messageCorrelation: crypto.randomUUID(),
                            header: "Header " + i,
                            payload: "Data " + i + " " + crypto.randomUUID(),
                            entryDate: moment.unix(Math.random() * 86400 + 1742300000 + i).toISOString(),
                            dueDate: moment.unix(Math.random() * 86400 + 1742320000 + i).toISOString(),
                            retries: outOfRetries ? 0 : null,
                            priority: 0,
                            queue: queue
                        }
                    }
                }
            }
            messages.map((message) => message.selected = false);
            if (onLoad) {
                onLoad(messages);
            }
        }
        return messages;
    }

    loadQueues = async () => {
        let loading = this.state.loadQueues;
        console.log("Loading Queues");
        let data = [];

        try {
            const response = await axios.get(queuesUri);
            data = response.data;
        } catch (error) {
            console.log(error.message);
        }

        let selected = this.props.selected || data.length === 0 ? this.props.selected : data[0].name;
        this.setState({queues: data, selected: selected, loadQueues: false }, () => this.selectQueue(selected, loading));
    }

    render() {
        const {selected} = this.props;
        return (
            <table>
                <caption>
                    <span className="buttons">
                        <label>
                            <input id="chk_outofretries" type="checkbox" name="outofretries"
                                checked={ this.state.outOfRetries } onChange={() => {this.toggleOutOfRetries()}}/>
                            Only&nbsp;out&nbsp;of&nbsp;retries
                        </label>
                        <label>
                            <input id="chk_autoRefresh" type="checkbox" name="autorefresh"
                                checked={ this.state.autoRefresh } onChange={() => {this.toggleAutoRefresh()}}/>
                            Auto&nbsp;Refresh
                        </label>
                        <label>Page&nbsp;Size
                            <select name="pageSize" id="pageSize" value={ this.state.pageSize } onChange={this.selectPageSize}>
                                <option key="20" value="20">20</option>
                                <option key="50" value="50">50</option>
                                <option key="100" value="100">100</option>
                                <option key="250" value="250">250</option>
                                <option key="500" value="500">500</option>
                            </select>
                        </label>
                    </span>
                    <span className="buttons">
                        <input id="txt_search" type="text" size="80" value={this.state.search} onChange={this.updateSearch}/>
                        <button id="btn_search" type="button" onClick={this.search} disabled={ this.state.loadQueues || !selected }>Search</button>
                    </span>
                </caption>
                <thead>
                    <tr>
                        <th style={{ minWidth: 200 }}>Queue</th>
                        <th style={{ width: 75 }}>Message Count</th>
                        <th style={{ width: 75 }}>Out of Retries</th>
                        <th style={{ minWidth: 200 }}>Next Queue</th>
                    </tr>
                </thead>
                <tbody id="tbl_queues">
                    {this.state.queues.map((queue) => (
                        <QueueItem key={queue.name} queue={queue} selected={selected} onSelect={() => this.selectQueue(queue.name, false) }/>
                    ))}
                </tbody>
            </table>
        )
    }
}

export default QueueTable;
