import React from 'react';
import QueueTable from './QueueTable';
import MessageTable from './MessageTable';

class Content extends React.Component {
    constructor(props) {
        super(props);
        this.state = { loading: true, queues: [], messages: [], selected: null, pageCount: 1, pageSize: 0, currentPage: 1 };
    }

    onComponentRefresh(queue, messages, queues, pageCount, pageSize, currentPage) {
        if (messages) {
            this.setState({
                selected: queue,
                messages: messages,
                queues: queues,
                pageCount: pageCount,
                pageSize: pageSize,
                currentPage: currentPage,
                loading: false
             });
        } else {
            this.setState({ selected: queue, loading: true, currentPage: 1 });
        }
    }

    render() {
        const { loading, messages, queues, selected, pageCount, pageSize, currentPage } = this.state;

        return (
            <div id="content-wrap">
                <div id="content">
                    <div id="main">
                        <div className="post">
                            <h1>Queues</h1>
                            <QueueTable key="queueTable" requestRefresh={loading} selected={ selected } currentPage={ currentPage }
                                onComponentRefresh={this.onComponentRefresh.bind(this)} />
                        </div>
                        <div className="post">
                            <h1>Messages { selected ? "in " + this.state.selected : "" }</h1>
                            <MessageTable messages={ messages } selected={ selected } queues={ queues }
                                pageCount={ pageCount } pageSize={ pageSize } currentPage={ currentPage }
                                onComponentRefresh={this.onComponentRefresh.bind(this)} />
                        </div>
                    </div>
                </div>
                <div id="popupContainer"></div>
            </div>
        )
    }
}

export default Content;
